"""Offline final audit: immutable v1 evidence, reviewed derivations, samples and handoff links."""
from pathlib import Path
from collections import Counter
from datetime import datetime, timezone
import csv
import hashlib
import json
import re
import subprocess

BASE=Path(__file__).resolve().parent
OUT=BASE/'evidence/final-review'
def read(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()


def main():
    # These original manifests are not regenerated by the review.
    manifests={}; referenced={}
    for name in ('cl13-a100','qwen-a100','oss120-a100','sol-a100','b100'):
        root=BASE/'evidence'/name
        m=read(root/'sha256.json')
        for f,h in m.items():
            p=root/f
            assert p.is_file() and sha(p)==h,(name,f)
        manifests[name]=dict(entries=len(m),manifest_sha256=sha(root/'sha256.json'))
    change=read(OUT/'scorer-change.json')
    assert sha(BASE/'score_candidate.py')==change['v1_sha256']
    assert sha(BASE/'score_candidate_v2.py')==change['v2_sha256']
    assert subprocess.check_output(['git','-C',str(BASE/'ujb'),'rev-parse','HEAD'],text=True).strip()=='e7b69a0b4f79d0d1896046079f6926d955f31452'
    assert subprocess.check_output(['git','-C',str(BASE/'ujb'),'status','--porcelain'],text=True)==''
    assert sha(BASE/'evidence/dataset-audit/heatmap-100.json')=='3e4c226648297ac9585195b9950c74db3dc59a0f5d336e552f667bcc12388546'
    r=read(OUT/'recomputed.json');rows=r['rows']
    assert sha(BASE/'rebuild_delivery.py')==r['rebuild_script_sha256']
    assert Counter(x['status'] for x in rows)=={'pass':273,'fail':525,'timeout_unresolved':1,'infrastructure_unresolved':1}
    assert len(rows)==800 and r['determinate_answers']==798 and r['determinate_AB_pairs']==398
    assert len(r['changes'])==1 and r['changes'][0]['task_idx']==48
    assert r['cost']['usd']=='1.1202265' and r['cost']['model_requests']==205
    # Record all scoring artifacts referred to by the actual 800 answers, not only a green summary.
    results={x[k] for x in rows for k in ('v1_result','result')}
    command_logs=0
    for f in sorted(results):
        p=BASE/f;s=read(p)
        for child in p.parent.iterdir():
            if child.is_file():referenced[str(child.relative_to(BASE))]=sha(child)
        for c in s['commands']:
            assert (p.parent/c['stdout']).exists() and (p.parent/c['stderr']).exists()
            command_logs+=2
    cells=list(csv.DictReader((OUT/'cells.csv').open()))
    assert len(cells)==40
    for c in cells:
        matching=[x for x in rows if (x['task'],x['model'],x['column'])==(c['task'],c['model'],c['column'])]
        assert len(matching)==20
        assert int(c['passed'])==sum(x['status']=='pass' for x in matching)
        assert int(c['failed'])==sum(x['status']=='fail' for x in matching)
        assert int(c['unknown'])==sum(x['status'] not in ('pass','fail') for x in matching)
    pairs=list(csv.DictReader((OUT/'paired.csv').open()));assert len(pairs)==20
    assert sum(int(p['determinate_pairs']) for p in pairs)==398
    for p in pairs:
        old=r['paired'][p['model']][p['task']]
        assert int(p['gain'])==old['left_only'] and int(p['loss'])==old['right_only']
    samples=read(OUT/'samples.json');assert len(samples)==11
    for task in ('FCG','CTG','ITG','APR','DD'):
        assert {s['status'] for s in samples if s['task']==task}=={'pass','fail'}
    for x in rows:
        if x['task']=='ITG' and x['status']=='pass':
            assert x['details']['itg_failure_in_inserted_test']
    close=read(OUT/'resource-closeout.json')
    assert not close['owned_queued_jobs'] and not close['local_owned_processes']
    assert not close['jobs_cancelled'] and not close['other_jobs_modified']
    assert close['api_responses']==205 and close['api_unknown_dispatches']==0 and close['ledger_reserved_usd']==0
    doc=BASE/'复现交接.md';links=[]
    for target in re.findall(r'\]\(([^)]+)\)',doc.read_text()):
        if '://' in target or target.startswith('#'):continue
        p=(doc.parent/target.split('#')[0]).resolve();assert p.exists(),target;links.append(target)
    assert 'C–E' in doc.read_text() and '不是最终结算账单' in doc.read_text()
    for ext in ('png','svg','pdf'):assert (OUT/f'heatmap-reviewed.{ext}').stat().st_size>1000
    (OUT/'scoring-artifacts-sha256.json').write_text(json.dumps(referenced,indent=2)+'\n')
    audit=dict(status='complete',verified_at=datetime.now(timezone.utc).isoformat(),
               old_manifests_verified=manifests,old_scorer_unchanged=True,official_repo_clean=True,
               referenced_results=len(results),referenced_artifacts=len(referenced),command_log_files=command_logs,
               formal_answers=800,determinate_answers=798,determinate_pairs=398,version_changes=1,
               manual_samples=11,passing_itg_stacks=27,chart_observed_cells=40,chart_unrun_gray_cells=60,
               handoff_links_verified=len(links),api_usage_cost_usd=r['cost']['usd'],
               resource_closeout_sha256=sha(OUT/'resource-closeout.json'),new_model_requests_in_review=0,
               bounded_java_rescores_in_review=1,
               handoff_sha256=sha(doc),recompute_sha256=sha(OUT/'recomputed.json'))
    (OUT/'completion-audit.json').write_text(json.dumps(audit,indent=2)+'\n')
    print(json.dumps(audit,indent=2))


if __name__=='__main__':main()
